class Node {
  constructor(key) {
    this.key = key;
    this.left = null;
    this.right = null;
    this.height = 1;
  }
}

const height = (n) => (n ? n.height : 0);
const balanceFactor = (n) => (n ? height(n.left) - height(n.right) : 0);
const update = (n) => { n.height = 1 + Math.max(height(n.left), height(n.right)); };

function rotateRight(y) {
  const x = y.left;
  y.left = x.right;
  x.right = y;
  update(y);
  update(x);
  return x;
}

function rotateLeft(x) {
  const y = x.right;
  x.right = y.left;
  y.left = x;
  update(x);
  update(y);
  return y;
}

function insert(node, key) {
  if (!node) return new Node(key);
  if (key < node.key) node.left = insert(node.left, key);
  else if (key > node.key) node.right = insert(node.right, key);
  else return node;
  update(node);
  const bf = balanceFactor(node);
  if (bf > 1 && key < node.left.key) return rotateRight(node);
  if (bf < -1 && key > node.right.key) return rotateLeft(node);
  if (bf > 1 && key > node.left.key) { node.left = rotateLeft(node.left); return rotateRight(node); }
  if (bf < -1 && key < node.right.key) { node.right = rotateRight(node.right); return rotateLeft(node); }
  return node;
}

let root = null;
for (const k of [10, 20, 30, 40, 50, 25]) root = insert(root, k);
console.log('balanced root:', root.key);

